import json, os, sys, traceback, shutil, stat, tempfile
import fsutil

OUT = []
def rec(name, fn):
    try:
        v = fn()
        OUT.append((name, "OK", repr(v)))
    except BaseException as e:
        OUT.append((name, "EXC", f"{type(e).__name__}: {e}"))

base = tempfile.mkdtemp(prefix="dt-")
def p(*a):
    return os.path.join(base, *a)

