import datetime as _dt
from decimal import Decimal

now = _dt.datetime(2023, 5, 17, 12, 34, 56, 789012)
JSONCASES = {
    "datetime": {"d": now},
    "date": {"d": _dt.date(2023, 5, 17)},
    "time": {"d": _dt.time(12, 34, 56)},
    "set": {"s": {3, 1, 2}},
    "decimal": {"x": Decimal("3.33")},
    "nested": {"a": [1, {"b": (1, 2)}, None, True], "c": {"d": {"e": [Decimal("1.5")]}}},
    "unicode": {"theme": "dark", "language": "中文", "emoji": "😀"},
    "numbers": {"i": 10, "f": 1.5, "n": float("nan"), "inf": float("inf")},
    "bytes": {"b": b"abc"},
    "complex": {"c": complex(1, 2)},
    "tuplekey": {(1, 2): "x"},
}
for tag, data in JSONCASES.items():
    for kw in (
        {},
        {"indent": 2},
        {"indent": 4, "sort_keys": True},
        {"sort_keys": True},
        {"ensure_ascii": False},
        {"separators": (",", ":")},
        {"indent": "\t"},
        {"skipkeys": True},
        {"allow_nan": False},
        {"check_circular": False},
    ):
        def go(tag=tag, data=data, kw=kw):
            f = p(f"J_{tag}_{abs(hash(str(sorted(kw.items()))))}.json")
            fsutil.write_file_json(f, data=data, **kw)
            with open(f, "rb") as fh:
                return fh.read()
        rec(f"json[{tag}] {sorted(kw.items())}", go)

